						event.preventDefault();
						event.stopPropagation();
						addItem();
				}
			}
		};
		modalElem.addEventListener('keydown', handleEnter);

		modal.addEventListener('hidden.bs.modal', function cleanup() {
			modalElem.removeEventListener('keydown', handleEnter);
		}, { once: true });
	});
});

