					.flatMap(g -> g.getMembers().stream())
					.map(Member::getUserId)
					.collect(Collectors.toSet()));
		}
		catch (IdUnusedException e)
		{
			log.warn("Could not find site for context {}", context, e);
			return Optional.of(Set.of());
		}
	}
