<script>
function submitCommand(button, command) {
    SPNR.disableControlsAndSpin(button, null);
    setTimeout(() => {
        const form = button.closest('form') || document.querySelector('form');
        if (form) {
            const input = document.createElement('input');
            input.type = 'hidden';
            input.name = 'command';
            input.value = command;
            form.appendChild(input);
            form.submit();
        }
    }, 100);
}
</script>

